mapper.select:
/* * SQL-ID : isry.couns.taskwksprt.etxpyaplyandinq.mapper.NgtmWorkEtxpyAplyMapper.selectNgtmWorkEtxpyAplyList : 야간근무수당신청 LIST * 작성자 : 2023.05.16 - Jeong.Won.Je */ WITH PENSN AS ( SELECT NIGHT_WORK_UNTPC_AMT , WIK_OVTIME_UNTPC_AMT , NIGHT_OVTIME_UNTPC_AMT FROM AYC380 WHERE 1=1 AND CRTR_YR = SUBSTR(#{YYYYMM}, 0, 4) ) , NIGHT AS ( SELECT A1.USER_ID AS USER_ID , C##RG.DEC_B64(A4.FLNM_ENCPT) AS USER_FLNM , A1.WORK_YMD AS WORK_YMD
, CASE WHEN A2.BGNG_HR > '18:00' THEN CASE WHEN A2.END_HR > '22:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR <= '02:00' THEN FLOOR(((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(A1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR > '02:00' AND A2.END_HR < '04:00' THEN FLOOR(((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END WHEN A2.BGNG_HR < '06:00' THEN CASE WHEN A2.END_HR >= '04:00' AND A2.END_HR <= '06:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR > '06:00' AND A2.END_HR < '10:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || '060001', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END ELSE 0 END AS WTIME
, A2.BGNG_HR || ' ~ ' || A2.END_HR || ' 근무' AS BIGO , ( SELECT COUNT(*) FROM ( SELECT C1.USER_ID , C1.VCATN_SE_CD , C1.VCATN_BGNG_YMD , C1.VCATN_END_YMD FROM AYC130 C1 WHERE 1=1 AND C1.USER_ID = A1.USER_ID AND C1.DEL_YN = 'N' AND C1.APLY_SE_CD = '01' AND C1.APRV_STTS_SE_CD = '2' AND A1.WORK_YMD BETWEEN C1.VCATN_BGNG_YMD AND C1.VCATN_END_YMD GROUP BY C1.USER_ID, C1.VCATN_SE_CD, C1.VCATN_BGNG_YMD, C1.VCATN_END_YMD ) ) AS VCATN_YN FROM AYC100 A1 , AYC110 A2 , SAA200 A3 , SCA100 A4 WHERE 1=1 AND A1.USER_ID = #{USER_ID} AND SUBSTR(A1.WORK_YMD, 0, 6) = #{YYYYMM} AND A1.DEL_YN = 'N' AND A2.BIZ_PLAN_MNG_NO = A1.BIZ_PLAN_MNG_NO AND A2.DEL_YN = 'N' AND A3.USER_ID = A1.USER_ID AND A4.ENFSN_NO = A3.ENFSN_NO AND A4.DEL_YN = 'N' ) SELECT NIGHT.USER_ID AS USER_ID , NIGHT.USER_FLNM AS USER_FLNM , NIGHT.WORK_YMD AS WORK_YMD , NIGHT.WTIME AS WTIME , NIGHT.BIGO AS BIGO , NIGHT.VCATN_YN AS VCATN_YN , SUM(NIGHT.WTIME) OVER() AS SSUM , TRUNC(SUM(NIGHT.WTIME) OVER() / 60 * PENSN.NIGHT_WORK_UNTPC_AMT, -1) AS AAMT FROM NIGHT , PENSN WHERE 1=1 AND NIGHT.VCATN_YN = 0 AND NOT NIGHT.WTIME = 0 ORDER BY NIGHT.WORK_YMD ASC
